from pathlib import Path
import json,html
root=Path(__file__).parent
ds=json.loads((root/'designs.json').read_text());css=(root/'prototype.css').read_text();js=(root/'prototype.js').read_text()
labels={'concept':'中心思想','problem':'解決する問題','home':'ホーム構造','mobile':'スマートフォン','pc':'PC','nav':'ナビゲーション','hierarchy':'情報の階層','graph':'グラフ・表現','pros':'メリット','cons':'デメリット','difficulty':'実装難易度','extend':'将来的な拡張性'}
for d in ds:
 folder=root/f'design-{d["id"]:02}';folder.mkdir(exist_ok=True)
 tokens=';'.join(f'--{k}:{d[k]}' for k in ['bg','surface','primary','accent','text','muted','border','radius'])+';--success:#34735D;--warning:#966009;--error:#AF3846;--soft:color-mix(in srgb,var(--primary) 7%,var(--surface));--track:color-mix(in srgb,var(--primary) 10%,var(--surface));--chart-muted:color-mix(in srgb,var(--primary) 50%,var(--surface));'
 page=f'<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><title>{d["name"]} | Studyplus デザイン案</title><style>:root{{{tokens}}}\n{css}</style><body class="d{d["id"]}"><div id="app"></div><script>window.DESIGN={json.dumps(d,ensure_ascii=False)};\n{js}</script></body></html>'
 (folder/'index.html').write_text(page)
 md=f'# {d["id"]:02} {d["name"]} — {d["ja"]}\n\n{d["degree"]}\n\n'
 for k,l in labels.items():md+=f'## {l}\n\n{d[k]}\n\n'
 md+='## デザイントークン\n\n|役割|値|\n|---|---|\n'
 for k,l in [('bg','背景'),('surface','Surface'),('primary','Primary'),('accent','Accent'),('text','Text'),('muted','Subtext'),('border','Border'),('radius','角丸'),('shadow','影'),('space','余白'),('type','タイポグラフィ')]:md+=f'|{l}|{d[k]}|\n'
 md+='|Success|#34735D|\n|Warning|#966009|\n|Error|#AF3846|\n|Chart Colors|数学 #4368A0、英語 #A36E42、物理 #4B817B、化学 #8E6A98。ユーザー色を優先。全体比較はPrimaryと中間グレー。|\n\n状態色は役割別。色だけで状態を伝えない。背景・Surface・Text・Borderを意味トークンとして管理し、将来のダーク配色で置換できる設計。今回のカンプはライトのみ。\n'
 (folder/'DESIGN.md').write_text(md)
# Comparison portal
style='''*{box-sizing:border-box}body{margin:0;background:#f3f4f6;color:#25313c;font:15px/1.8 -apple-system,"Noto Sans CJK JP",sans-serif}a{color:#24585d}header{padding:64px max(24px,calc((100vw - 1200px)/2));background:#1e3038;color:white}header h1{font-size:clamp(28px,4vw,48px);line-height:1.4;letter-spacing:-.04em;max-width:900px;margin:12px 0 24px}header p{max-width:760px;color:#d1dce1}header small{letter-spacing:.16em;color:#a8c3c6}.wrap{max-width:1260px;margin:auto;padding:30px 24px 70px}.controls{position:sticky;top:0;z-index:9;display:flex;align-items:center;flex-wrap:wrap;gap:8px;padding:13px 24px;background:#ffffffed;border-bottom:1px solid #d8dfe4}.controls a,.controls button,.btn{display:inline-block;padding:8px 13px;background:white;border:1px solid #c5d0d6;color:#25313c;border-radius:5px;min-height:44px;font:inherit;text-decoration:none;cursor:pointer}.controls button.active,.btn.primary{background:#24585d;color:white;border-color:#24585d}h2{font-size:25px;letter-spacing:-.03em}h3{font-size:20px}p{margin:10px 0}.note{font-size:13px;color:#586b77}.callout{border-left:3px solid #24585d;background:#e5eeec;padding:20px 24px;margin:25px 0}.cards{display:grid;grid-template-columns:1fr 1fr;gap:24px}.card{background:white;border:1px solid #d9e0e5;padding:24px;border-radius:10px}.card.recommended{border:2px solid #24585d;padding:23px}.card h3{margin:4px 0}.tag{display:inline-block;font-size:12px;background:#e7eeee;color:#31575c;padding:3px 8px;border-radius:4px}.card .copy{min-height:85px;font-size:14px}.preview{background:#eff2f4;display:flex;justify-content:center;border:1px solid #d9e0e5;max-height:440px;overflow:hidden;margin:20px 0}.preview img{display:block;width:100%;height:auto;object-fit:contain;object-position:top}.preview.mobile img{width:195px;box-shadow:0 3px 20px #192d331a}.card .buttons{display:flex;gap:8px;flex-wrap:wrap}.card .buttons a{font-size:13px}.card details{border-top:1px solid #e0e5e9;margin-top:20px;padding-top:14px}.card summary{cursor:pointer;min-height:44px;font-weight:600}.card dl{font-size:13px}.card dt{font-weight:700;margin-top:13px}.card dd{margin:4px 0;color:#52636f}.swatches{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0}.swatches span{width:28px;height:28px;border-radius:50%;border:1px solid #c8d0d5}.wide{overflow:auto}table{border-collapse:collapse;min-width:700px;width:100%;font-size:13px;background:white}th,td{border-bottom:1px solid #d9e0e5;padding:12px;text-align:left;vertical-align:top}th{background:#e7ecef;white-space:nowrap}.scores td:not(:first-child){text-align:center}.scores tr.recommend{background:#e8f0ee}.current-grid{display:grid;grid-template-columns:1.5fr 1fr;gap:24px}.current-grid img{width:100%;max-height:620px;object-fit:contain;object-position:top}.current-grid a{background:#e5e9ed;display:block}section{scroll-margin-top:85px;margin-bottom:48px}.findings{display:grid;grid-template-columns:1fr 1fr;gap:16px}.findings article{padding:22px;background:white;border-left:3px solid #99acb6}.findings h3{margin:0;font-size:16px}.findings p{font-size:14px}code{font-size:12px;background:#e9ecef;padding:2px 5px}footer{color:#5d6c78;font-size:13px;border-top:1px solid #ccd5dc;padding:20px 0}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid #24585d;outline-offset:3px}@media(max-width:767px){header{padding:32px 20px}.wrap{padding:20px 16px}.cards,.findings,.current-grid{grid-template-columns:1fr}.controls{padding:8px 12px;gap:5px}.controls a,.controls button{font-size:12px;padding:7px 9px}.card{padding:18px}.card.recommended{padding:17px}.preview{max-height:500px}.card .copy{min-height:0}.preview.mobile img{width:230px}}'''
analysis='''<section id="current"><h2>現状：情報の不足ではなく、重み付けの不足</h2><p>ソースと実Chromiumで確認。1440pxのホームは1画面に収まりますが、390pxではページ高1,614px。今日の数字→開始→科目一覧→グラフの順で、推移が初期画面から遠くなっています。全7ページ×2幅でページ横はみ出しは見られませんでした。</p><div class="current-grid"><a href="current/dashboard-1440.png"><img src="current/dashboard-1440.png" alt="現行PCホーム、同じ合成データ"></a><a href="current/dashboard-390.png"><img src="current/dashboard-390.png" alt="現行スマホホーム、同じ合成データ"></a></div><p class="note">画像を開くと原寸で確認できます。比較用データ：2026/10/15、今日130分、直接目標180分、週実績610分・目標1260分。記録なしの化学も含む。実データ・実同期先は未使用。</p><div class="findings"><article><h3>1. 全情報が同じ声量</h3><p>各カードに見出し・説明・罫線が反復し、概要と補助情報の違いが弱い。主数値／比較／詳細の3段階にし、独立カードは意味のある単位だけに限定する。</p></article><article><h3>2. 行動と数値が分離</h3><p>今日の目標、教材選択、記録方法、開始が離れている。選択内容を維持した開始面を今日の数値の隣に置き、開始方法の再選択を減らす。</p></article><article><h3>3. スマホで図が遅い</h3><p>科目4行と教材説明がグラフより先にある。小さい推移を上げ、教材の完全な内訳は科目行を展開して読む。すべてを折り畳むのではなく主要4情報は初期表示する。</p></article><article><h3>4. グラフの解釈負担</h3><p>軸の時間単位、未完了の今日、比較期間を見える位置に置く。数値とグラフを一体にし、装飾のリングや多色グラフを増やさない。</p></article><article><h3>5. ナビと入口の分散</h3><p>スマホ7項目はラベルが小さく、記録一覧は学習時間か設定メニューにある。毎日の行動とデータ管理を分け、記録を直接辿れる構造を比較する。</p></article><article><h3>6. 部品のルールが不揃い</h3><p>Panel/Stats/Chart/Pickとネイティブselectが混在。CSSは後段の上書きが多く、入力・ボタン・見出しの規格が揺れる。意味トークンと部品のバリエーションを少数に揃える。</p></article><article><h3>7. 機能を隠して整理しない</h3><p>期間選択・目標・模試・AI・全記録・評価式は残す。各案の「学習管理／ライブラリ」から既存機能の行き先を確認できる。タスク保存は現行にないため案5では新機能扱い。</p></article><article><h3>8. 状態と復旧もUX</h3><p>保存未完了・競合・他端末の計測は、通常時の数値と混ぜない。異常時に理由と復旧操作を出す。前回レビューのP-01/P-02は実装前の共通課題として扱い、見た目で解決済みにしない。</p></article></div></section>'''
maptable='''<section id="map"><h2>現行機能と、提案後の居場所</h2><div class="wide"><table><tr><th>現行機能</th><th>実装・役割</th><th>全案での扱い</th></tr><tr><td>ホーム</td><td>TodayHome：今日/候補/科目/7日</td><td>今日・週・グラフ・開始を常時。構造は7通り。</td></tr><tr><td>手入力・計測</td><td>StudyRecorder、ManualRecordForm、タイマー共有/PiP</td><td>教材と方法を保持して開始。未保存時間を別表示。</td></tr><tr><td>学習時間・長期</td><td>TimeView、LongView：期間/曜日/累積/異常値</td><td>分析へ。概要→比較→根拠の順。</td></tr><tr><td>科目・教材</td><td>SubjectsView、MaterialsView：使用量/配分/目標/全記録</td><td>学習室/教材/管理。短期概要と全指標を分離。</td></tr><tr><td>週・目標・スコア</td><td>WeekView、Condition、Balance、Stability、GoalTable</td><td>週の主要値はホーム、詳細と式は分析/管理。</td></tr><tr><td>模試・AI</td><td>ExamsView、AIView：成績関連/外部分析パケット</td><td>管理/ライブラリ内に明示。機能は廃止しない。</td></tr><tr><td>記録一覧</td><td>RecordManager：検索/30件ページ/編集/削除確認</td><td>記録タブへ。日付・対象の絞り込みを提案。</td></tr><tr><td>設定・JSON・同期</td><td>DeviceSync、設定ダイアログ、IndexedDB</td><td>管理。競合は画面内に復旧導線を追加する設計。</td></tr><tr><td>タスク・予定</td><td>独立データなし。現在は科目候補のみ。</td><td>案5は新機能。案7の予定拡張も採用後の別設計。</td></tr></table></div><p class="note">PCはサイドバー＋複数カラム、スマホは767px以下で下部ナビとMobileAnalysisの切替。CSSには1050pxの中間境界も存在。現行はReact/TypeScript・Tailwindと独自CSS・Recharts・Radixを使用。分析関数と保存処理は既存資産として再利用可能。</p></section>'''
body=f'''<header><small>STUDYPLUS / DESIGN EXPLORATION</small><h1>情報は豊かに。<br>読む順序は、明快に。</h1><p>7つの異なる情報設計を、同じデータで比較します。PCとスマホのホーム、各案を特徴付ける主要画面、操作可能な独立HTMLを用意しました。</p><p>提案フェーズ · 本番UI未変更 · 2026年10月15日</p></header><nav class="controls"><a href="#designs">7案を見る</a><a href="#scores">評価表</a><a href="#recommend">推薦案</a><a href="#current">現状分析</a><button class="active" data-shot="mobile-home">スマホホーム</button><button data-shot="desktop-home">PCホーム</button><button data-shot="mobile-major">スマホ主要画面</button><button data-shot="desktop-major">PC主要画面</button></nav><main class="wrap"><section id="intro"><div class="callout"><strong>まずは案2「Flow Desk」から。</strong><p>今日と週の情報、選択中教材、学習開始を一体化し、グラフまでを短くします。さらに分析重視なら案3、教材中心なら案6も比較してください。</p></div><p class="note">使い方：上の切替で7枚を同条件で比較 → 気になる案を「操作する」で開く → 開始・方法切替・期間切替・管理メニューを試す。各案の実装難易度と注意点は「設計の説明」にあります。画像と数値は提案用で、実保存・同期は行いません。</p></section><section id="designs"><h2>7つの設計方向</h2><div class="cards">'''
for d in ds:
 n=f'{d["id"]:02}';spec=''.join(f'<dt>{label}</dt><dd>{html.escape(d[key])}</dd>' for key,label in labels.items())
 spec+='<dt>デザイントークン</dt><dd>'+ '<br>'.join(f'{label}：{html.escape(d[key])}' for key,label in [('bg','背景'),('surface','Surface'),('primary','Primary'),('accent','Accent'),('text','Text'),('muted','Subtext'),('border','Border'),('radius','角丸'),('shadow','影'),('space','余白'),('type','文字')])+'<br>Success #34735D / Warning #966009 / Error #AF3846<br>Chart：数学 #4368A0、英語 #A36E42、物理 #4B817B、化学 #8E6A98。ユーザー色を優先。</dd>'
 body+=f'''<article class="card {'recommended' if d['id']==2 else ''}" id="design{n}"><span class="tag">{n} · {d['degree']}</span><h3>{d['name']}</h3><p><strong>{d['ja']}</strong></p><p class="copy">{d['concept']}</p><a class="preview mobile" data-preview="{n}" href="screenshots/{n}-mobile-home.png"><img loading="lazy" src="screenshots/{n}-mobile-home.png" alt="{d['name']} スマホホーム"></a><div class="buttons"><a class="btn primary" href="design-{n}/index.html" target="_blank">ホームを操作する ↗</a><a class="btn" href="design-{n}/index.html?view={d['major']}" target="_blank">{d['majorName']} ↗</a></div><div class="swatches">{''.join(f'<span style="background:{d[k]}" title="{k}: {d[k]}"></span>' for k in ['bg','surface','primary','accent','text'])}</div><details><summary>設計の説明・メリット・注意点</summary><dl>{spec}</dl><a href="design-{n}/DESIGN.md">仕様をMarkdownで読む</a></details></article>'''
body+='</div></section><section id="scores"><h2>7案の比較評価</h2><p class="note">設計者による相対評価。ユーザーテスト結果ではありません。10点満点、高いほど良い。ただし「実装難易度」だけは10が最も難しい。性能や工数を実測した点数ではありません。</p><div class="wide"><table class="scores"><tr><th>評価軸</th>'+''.join(f'<th>{d["id"]:02}<br>{d["name"]}</th>' for d in ds)+'</tr>'
scorelabels=['見た目','情報の整理','情報量と見やすさ','スマホ操作性','PC操作性','学習開始','グラフ','統一感','実装難易度 ※高いほど難','保守性','拡張性','Studyplusとの相性']
for i,l in enumerate(scorelabels):body+=f'<tr class="{"recommend" if i==11 else ""}"><th>{l}</th>'+''.join(f'<td>{d["scores"][i]}</td>' for d in ds)+'</tr>'
body+='''</table></div></section><section id="recommend"><h2>推薦：02 Flow Desk</h2><p>「状況が分かる→そのまま始める」を、PC・スマホの両方で実現しやすい案です。カードを増やす代わりに、今日と週を同じ情報面にまとめます。開始操作を近づけながら、グラフの面積を確保でき、現行の記録・計測・集計処理を活かせます。</p><div class="callout"><strong>ハイブリッド案：Flow Desk ＋ Insight Lab ＋ Subject Studio</strong><p>ホームとナビは案2で統一。分析の詳細画面に案3の単位付き比較グラフと数値行を採用。科目・教材画面に案6の選択状態を保つ操作を採用します。3種類のナビや配色を混在させず、案2の部品規格へ統合します。</p></div><p>案5の予定管理は魅力がありますが、入力負担と保存・同期の新仕様が増えます。初回のデザイン改善には含めず、必要性を確認して追加するのが適切です。案7の週キャンバスは、週間分析の別表示として取り入れる余地があります。</p><h3>採用後の実装方針</h3><p>フレームワーク変更は現段階では不要です。現行のReact/TypeScriptと分析・保存関数を活かし、AppShell、ActionSurface、Metric、ChartFrame、EntityList、RecordSheetへ必要な範囲で分割。色・間隔・文字・状態を意味トークンに揃えます。既存データの移行を必要とするタスク機能や新しい計算式は別途設計します。</p><p>先に保存競合・同期競合からの復旧を整え、画面改修時に入力保持、選択中教材の引継ぎ、計測共有・PiP・JSON・オフライン版を検証します。案を選ぶまでは本番適用を行いません。</p></section>'''+analysis+maptable+'''<section id="limits"><h2>確認範囲とプロトタイプの限界</h2><p>現行は合成データを独立したChromium環境へ投入し、7ページを1440/390pxで確認。各案は360/390/430/1280/1440pxでホームと主要画面を点検し、390/1440pxの画像を出力しています。実機のiPhone、Windowsのネイティブ入力、キーボード表示、支援技術での読み上げは未確認です。単一HTMLは外部依存なしですが、この環境のポリシーがfile://を禁止するため、直接開く操作は未確認。画面検証はローカルHTTPで行いました。</p><p>プロトタイプはHTML/CSS/JavaScriptのみで、外部ライブラリ・通信・保存を使用しません。計測・検索・期間切替は操作感を確かめるデモ。管理内の模試/AI/同期/設定は既存機能の入口を示す説明画面です。7日以外の期間値、教材の長期値、計画は構成確認用の例で、分析結果ではありません。</p><p>全案の細かな入力画面やすべてのエラー状態を完成させたものではありません。採用案の決定後に、保存失敗・空データ・長い名称・競合・計測中などの状態設計を具体化します。</p></section><footer>本番の学習データ・同期先・UI・CSS・ビルド設定は変更していません。成果物は design-prototypes/ 内で独立しています。</footer></main><script>document.querySelectorAll('[data-shot]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-shot]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('[data-preview]').forEach(a=>{const src='screenshots/'+a.dataset.preview+'-'+b.dataset.shot+'.png';a.href=src;a.querySelector('img').src=src;a.querySelector('img').alt=b.textContent;a.classList.toggle('mobile',b.dataset.shot.startsWith('mobile'));});});</script>'''
(root/'index.html').write_text('<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Studyplus — 7つのデザイン案</title><style>'+style+'</style><body>'+body+'</body></html>')
print('Generated 7 standalone prototypes and comparison portal.')
